# Form data transcribed from EFDMS (Florida COE) and House Clerk filings, 2025 reporting year.
# Figures as filed. Home addresses omitted (only business addresses printed on the form are kept).

EFD = "https://disclosure.floridaethics.gov/Report/PrintForm/?filingId="
HIST = "https://disclosure.floridaethics.gov/PublicSearch/FilingHistory/"

def f6(fid, filed, nw, assets, income, liabs, biz, src, year=2025, typ="Form 6"):
    return {"type": typ, "year": year, "filed": filed, "url": EFD + str(fid), "netWorth": nw,
            "assets": assets, "incomeSources": income, "liabilities": liabs, "businesses": biz, "source": src}

def f1(fid, filed, assets, income, liabs, biz, src, year=2025, typ="Form 1"):
    return {"type": typ, "year": year, "filed": filed, "url": EFD + str(fid),
            "assets": assets, "incomeSources": income, "liabilities": liabs, "businesses": biz, "source": src}

A = lambda name, kind, value=None: {"name": name, "kind": kind, **({"value": value} if value is not None else {})}
I = lambda source, kind, amount=None: {"source": source, "kind": kind, **({"amount": amount} if amount is not None else {})}
L = lambda creditor, amount=None: {"creditor": creditor, **({"amount": amount} if amount is not None else {})}
B = lambda name, role, nature: {"name": name, "role": role, "nature": nature}

SRC6 = "Florida Commission on Ethics EFDMS, CE Form 6 (Full and Public Disclosure of Financial Interests), filing history "
SRC1 = "Florida Commission on Ethics EFDMS, CE Form 1 (Statement of Financial Interests), filing history "

